    {
      "name": "Pharmaceuticals — Vaccine Manufacturers",
      "impact": "headwind",
      "rationale": "Reduced routine recommendation list and MMR split directly cut guaranteed revenue streams for pediatric vaccines excluded from the new priority list."
    },
    {
      "name": "Pharmaceuticals — Core Antigen Producers",
      "impact": "tailwind",
      "rationale": "Companies with dominant positions in the 11 remaining diseases (DTaP, Polio, Hep B, etc.) see their franchise moat widen as alternatives are de-emphasized."
    },
    {
      "name": "Managed Care / Health Insurers",
