    },
    {
      "name": "Diagnostics & Lab Services",
      "impact": "tailwind",
      "rationale": "A shift toward individualized 'shared clinical decision-making' and separate MMR dosing increases pre-vaccination titer testing and doctor visits."
    }
  ],
